//! Deterministic sampling helpers on `Xoshiro256StarStar`. Only `+ - * /` and `round` on f64 (IEEE exact), never
//! `ln`/`exp`, so generated bytes do not depend on the platform's libm.

use qt_types::Xoshiro256StarStar;

/// Quantiles of Exp(1) at i/32, i = 0..=31 (rounded to 6 digits, so `-ln(1/2)` is written as 0.693147), then a
/// tail cap; sampled with linear interpolation.
#[allow(clippy::approx_constant)]
const EXP_Q: [f64; 33] = [
    0.0, 0.031749, 0.064539, 0.09844, 0.133531, 0.169899, 0.207639, 0.24686, 0.287682, 0.330242, 0.374693, 0.421213,
    0.470004, 0.521297, 0.575364, 0.632523, 0.693147, 0.757686, 0.826679, 0.900787, 0.980829, 1.067841, 1.163151,
    1.268511, 1.386294, 1.519826, 1.673976, 1.856298, 2.079442, 2.367124, 2.772589, 3.465736, 7.6,
];
/// Mean of the piecewise-linear distribution above.
const EXP_MEAN: f64 = 1.035_799_669_796_131_6;

/// CDF of the normalised `exp_ns` distribution at `x` (in units of its mean): exact for the piecewise-linear
/// quantile function above.
pub fn exp_cdf(x: f64) -> f64 {
    let y = x * EXP_MEAN;
    if y <= 0.0 {
        return 0.0;
    }
    for i in 0..32 {
        if y < EXP_Q[i + 1] {
            return (i as f64 + (y - EXP_Q[i]) / (EXP_Q[i + 1] - EXP_Q[i])) / 32.0;
        }
    }
    1.0
}

/// Size multipliers relative to the mean order size (heavy right tail, many small orders).
const SIZE_MULT: [f64; 18] = [
    0.02, 0.05, 0.1, 0.2, 0.25, 0.5, 0.5, 0.75, 1.0, 1.0, 1.0, 1.0, 1.5, 2.0, 2.0, 3.0, 4.0, 6.0,
];
/// Mean of `SIZE_MULT`.
const SIZE_MULT_MEAN: f64 = 24.87 / 18.0;

/// Thin wrapper adding distributions to the project RNG.
pub struct Rng(pub Xoshiro256StarStar);

impl Rng {
    /// New generator from a seed.
    pub fn new(seed: u64) -> Self {
        Self(Xoshiro256StarStar::new(seed))
    }

    /// Uniform in `[0, 1)`.
    pub fn f64(&mut self) -> f64 {
        self.0.next_f64()
    }

    /// True with probability `p`.
    pub fn chance(&mut self, p: f64) -> bool {
        self.f64() < p
    }

    /// Uniform integer in `lo..=hi` (`hi < lo` gives `lo`).
    pub fn range(&mut self, lo: u64, hi: u64) -> u64 {
        self.0.range_inclusive(lo, hi)
    }

    /// Uniform index in `0..n` (`n = 0` gives 0).
    pub fn index(&mut self, n: usize) -> usize {
        if n == 0 {
            0
        } else {
            self.range(0, n as u64 - 1) as usize
        }
    }

    /// Approximately exponential with the given mean (ns), rounded to an integer, >= 0.
    pub fn exp_ns(&mut self, mean: f64) -> i64 {
        let u = self.f64() * 32.0;
        let i = (u as usize).min(31);
        let frac = u - i as f64;
        let x = EXP_Q[i] + (EXP_Q[i + 1] - EXP_Q[i]) * frac;
        (x / EXP_MEAN * mean).round().max(0.0) as i64
    }

    /// Order size with the given mean (>= 1); for means >= 100, 60% are rounded to round lots of 100.
    pub fn size(&mut self, mean: u64) -> u64 {
        let m = SIZE_MULT[self.index(SIZE_MULT.len())];
        let raw = (mean.max(1) as f64 * m / SIZE_MULT_MEAN).round().max(1.0) as u64;
        if mean >= 100 && self.chance(0.6) {
            (raw.div_ceil(100)).max(1) * 100
        } else {
            raw
        }
    }

    /// Picks an index from non-negative weights (all zero gives 0).
    pub fn weighted(&mut self, w: &[f64]) -> usize {
        let total: f64 = w.iter().map(|x| x.max(0.0)).sum();
        if total <= 0.0 {
            return 0;
        }
        let mut u = self.f64() * total;
        for (i, x) in w.iter().enumerate() {
            let x = x.max(0.0);
            if u < x {
                return i;
            }
            u -= x;
        }
        w.iter().rposition(|x| *x > 0.0).unwrap_or(0)
    }
}
